// /spec/plan/owner_map/helpers/[]: One helper's owned set.
struct OwnedSet {
    // Digest of this helper's owned set (spec §4).
    std::string owned_sha256;
    // Number of owned experts; equals `experts.length`.
    int64_t count;
    // Device bytes of the owned experts.
    int64_t bytes;
    // Owned `[layer, expert]` pairs in selection order.
    std::vector<std::array<int64_t, 2>> experts;
};

// /spec/plan/owner_map: Initial expert ownership; the live mailbox epochs own later placement (spec §4).
struct OwnerMap {
    // Digest of all helpers' owned sets in helper order (spec §4).
    std::string owner_map_sha256;
    // Owned sets, aligned by index with `processes.helpers`.
    std::vector<OwnedSet> helpers;
};

// /spec/plan/engine_memory: The engine's measured memory plan and its cache identity (spec §5).
struct EngineMemory {
    // Plan cache format; exactly 1.
    int64_t cache_version;
    // Plan cache key (spec §5.1).
    std::string cache_key;
    // Model container identity.
    std::string model_identity;
    // Radiance binary and runtime identity.
    std::string engine_identity;
    // The measured plan the live plan is checked against (spec §5.2).
    EnginePlan expected;
};

// /spec/plan: Measured and planned state the engine and helpers verify at start-up.
struct Plan {
    // Initial expert ownership; the live mailbox epochs own later placement (spec §4).
    OwnerMap owner_map;
    // The engine's measured memory plan and its cache identity (spec §5).
    EngineMemory engine_memory;
};

// /spec/experiment/placement: Live placement experiment.
struct ExperimentPlacement {
    // `observe` (no change) or `forced_churn` (requires `at_step`).
    PlacementMode mode;
    // Step at which a forced churn happens.
    std::optional<int64_t> at_step;
};

// /spec/experiment/shape/helpers/[]: One role's lab override.
struct ShapePatch {
    // Role the override applies to.
    std::string role;
    // Partial helper settings for that role.
    HelperPatch settings;
};

// /spec/experiment/shape: Lab overlay of helper settings, applied after the per-role patches.
struct ExperimentShape {
    // Partial override for every helper.
    std::optional<HelperPatch> helper_common;
    // Per-role partial overrides.
    std::optional<std::vector<ShapePatch>> helpers;
};

// /spec/experiment/diagnostics/gemv: GEMV diagnostics.
struct GemvDiagnostics {
    // GEMV probe mode (0, 1 or 2).
    std::optional<int64_t> probe_mode;
    // Trace GEMV path refusals.
    std::optional<bool> refusal_trace;
};

// /spec/experiment/diagnostics/lanes: Lane diagnostics.
struct LaneDiagnostics {
    // Lane capture file; null disables capture.
    std::optional<std::optional<std::string>> capture_file;
    // Capture every Nth request.
    std::optional<int64_t> capture_every;
    // Most requests captured.
    std::optional<int64_t> capture_max;
    // Lane trace verbosity.
    std::optional<int64_t> trace_level;
    // Test hook stop point; null disables it.
    std::optional<std::optional<std::string>> test_stop_at;
};

// /spec/experiment/diagnostics/kernels: Kernel diagnostics.
struct KernelDiagnostics {
    // Plugin library to load instead; null keeps the configured one.
    std::optional<std::optional<std::string>> plugin_override;
    // Fill pattern for uninitialized outputs.
    std::optional<Poison> poison;
    // Shorten kernel sweeps.
    std::optional<bool> sweep_fast;
};

// /spec/experiment/diagnostics: Lab diagnostics by concern.
struct Diagnostics {
    // GEMV diagnostics.
    std::optional<GemvDiagnostics> gemv;
    // Lane diagnostics.
    std::optional<LaneDiagnostics> lanes;
    // Kernel diagnostics.
    std::optional<KernelDiagnostics> kernels;
};

// /spec/experiment: Lab-only experiments; forbidden when the profile is `production`.
struct Experiment {
    // Live placement experiment.
    std::optional<ExperimentPlacement> placement;
    // Lab overlay of helper settings, applied after the per-role patches.
    std::optional<ExperimentShape> shape;
    // Lab diagnostics by concern.
    std::optional<Diagnostics> diagnostics;
};

// /spec: The resolved serving configuration. `experiment` is present only when the profile is `lab`.
struct Spec {
    // What the operator asked for: model, layout and service policy.
    Intent intent;
    // Detected host and GPU facts the resolution used.
    Facts facts;
    // Selected calibrated parameters, each with its evidence.
    std::vector<CalibrationEntry> calibration;
    // Derived resource allocation.
    Resources resources;
    // The one shared remote-MoE handoff configuration.
    Handoff handoff;
    // Per-process settings.
    Processes processes;
    // Measured and planned state the engine and helpers verify at start-up.
    Plan plan;
    // Lab-only experiments; forbidden when the profile is `production`.
    std::optional<Experiment> experiment;
};

// /provenance/*: Provenance of the value at the key's JSON Pointer.
struct ProvenanceRecord {
    // Input layer that set the value.
    Origin origin;
    // Human-readable source: file and key, detector or derivation.
    std::string source;
    // Kind of value: operator policy, detected fact, derived, tuned (calibrated) or diagnostic.
    ValueClass value_class;
    // When the value may change: only at start-up, at a step boundary, or live.
    Lifecycle lifecycle;
    // Exact, measured or estimated.
    Confidence confidence;
    // JSON Pointers of the values this one was derived from.
    std::vector<std::string> inputs;
};

// (document): A serving manifest v1 document.
struct Manifest {
    // Contract identity; exactly `bigcherry/v1`.
    std::string api_version;
    // Document kind; exactly `ServingManifest`.
    std::string kind;
    // Identity of this resolved serving instance and its producer.
    Metadata metadata;
    // The resolved serving configuration. `experiment` is present only when the profile is `lab`.
    Spec spec;
    // Map from a JSON Pointer to the record of where that value (and its descendants) came from; the root "" record is
    // required (spec §7).
    std::map<std::string, ProvenanceRecord> provenance;
};

// Every registry field (patch copies excepted), in registry order: the metadata explain and provenance use.
struct FieldInfo {
    std::string_view path;             // JSON Pointer, or "$defs/<name>/..." inside a shared type
    std::string_view kind;
    std::string_view value_class;      // provenance class of the subtree (contract [[class_default]])
    bool required;
    bool nullable;
    std::string_view radiance_option;  // the engine flag the field binds to, or empty
    std::string_view radiance_config;  // its native Config destination, or empty
    std::string_view doc;
};
